<script setup lang="ts">
import{notificationStatus}from'../../shared/notification-status';
import{computed,onUnmounted,ref,watch}from'vue';
import{NAlert,NButton,NCard,NDrawer,NDrawerContent,NEmpty,NSelect,NSpace,NSpin,NTag}from'naive-ui';
import type{WorkItemProjection,WorkItemStatus}from'@dentity/contracts';
import{api,ApiError,errorMessage,type Entity,type Workspace}from'../../shared/api';
import PageHeader from '../../shared/ui/PageHeader.vue';import InfoHint from '../../shared/ui/InfoHint.vue';
const props=defineProps<{workspace:Workspace;entities:Entity[];enabled:boolean;selectedId?:string|undefined}>(),emit=defineEmits<{sessionExpired:[];selected:[id:string|undefined]}>();
const labels:Record<WorkItemStatus,string>={pending:'待处理',in_progress:'处理中',waiting:'等待中',awaiting_acceptance:'待验收',completed:'完成',canceled:'取消',failed:'失败'},states=Object.keys(labels)as WorkItemStatus[];
interface Detail{notifications?:{id:string;generationState:string;deliveryState:string;error:string|null}[];item:WorkItemProjection;assignments:{id:string;kind?:'work'|'acceptance';employeeId:string;sourceEmployeeId:string;summary:string;createdAt:number}[];events:{id:number;kind:string;body:Record<string,unknown>;createdAt:number;assignmentId:string}[];nextCursor:number|null}
const rows=ref<WorkItemProjection[]>([]),cursor=ref<string|null>(null),busy=ref(false),error=ref(''),status=ref('all'),employee=ref<string|null>(null),detail=ref<Detail|null>(null),detailBusy=ref(false),detailError=ref('');let generation=0,controller=new AbortController(),detailController=new AbortController();
const base=computed(()=>`/workspaces/${encodeURIComponent(props.workspace.id)}/work-items`),employeeName=(id:string)=>props.entities.find(e=>e.id===id)?.name??'数字员工',visibleStates=computed(()=>status.value==='all'?states:states.filter(s=>s===status.value));
const date=(n:number)=>new Date(n).toLocaleString('zh-CN',{hour12:false});
async function load(more=false){if(busy.value||!props.enabled)return;const version=generation,path=base.value;busy.value=true;error.value='';try{const q=new URLSearchParams({limit:'100',status:status.value,...(employee.value?{employeeId:employee.value}:{}),...(more&&cursor.value?{cursor:cursor.value}:{})}),result=await api<{items:WorkItemProjection[];nextCursor:string|null}>(path+'?'+q,controller.signal);if(version===generation&&path===base.value){rows.value=more?[...rows.value,...result.items]:result.items;cursor.value=result.nextCursor;}}catch(e){if(version===generation&&!controller.signal.aborted){error.value=errorMessage(e);if(e instanceof ApiError&&e.status===401)emit('sessionExpired');}}finally{if(version===generation)busy.value=false;}}
async function read(id:string,more=false){detailController.abort();detailController=new AbortController();const signal=detailController.signal,version=generation;detailBusy.value=true;detailError.value='';try{const next=more?detail.value?.nextCursor:null,result=await api<Detail>(base.value+'/'+encodeURIComponent(id)+(next?'?after='+next:''),signal);if(version===generation&&!signal.aborted)detail.value=more&&detail.value?{...result,events:[...detail.value.events,...result.events]}:result;}catch(e){if(version===generation&&!signal.aborted){detailError.value=errorMessage(e);if(e instanceof ApiError&&e.status===401)emit('sessionExpired');}}finally{if(version===generation&&!signal.aborted)detailBusy.value=false;}}
function reset(){generation++;controller.abort();detailController.abort();controller=new AbortController();rows.value=[];cursor.value=null;detail.value=null;busy.value=false;detailBusy.value=false;error.value='';detailError.value='';void load();if(props.selectedId)void read(props.selectedId);}
watch([()=>props.workspace.id,()=>props.enabled],reset,{immediate:true});watch([status,employee],()=>{generation++;controller.abort();controller=new AbortController();busy.value=false;void load();});watch(()=>props.selectedId,id=>{detail.value=null;if(id)void read(id);else detailController.abort();});
const timer=setInterval(()=>{if(!busy.value&&!cursor.value)void load();},5000);onUnmounted(()=>{generation++;controller.abort();detailController.abort();clearInterval(timer);});
</script>
<template><section class="work-items-page"><PageHeader title="事项看板"><NSpace><InfoHint text="工作区成员可查看必要业务进展。原私聊、群历史、文件和执行记录仍独立授权；首次交接自动建立事项，执行员工通过工具推进和交接。人的决定通过通用人工确认完成。" label="事项看板说明"/><NButton :loading="busy" :disabled="!enabled" @click="load()">刷新</NButton></NSpace></PageHeader><NAlert v-if="!enabled" type="info">事项 Beta尚未开启或运行状态暂不可确认。</NAlert><template v-else><NSpace class="board-filters"><NSelect v-model:value="status" :options="[{label:'全部状态',value:'all'},...states.map(s=>({label:labels[s],value:s}))]" aria-label="事项状态筛选"/><NSelect v-model:value="employee" clearable filterable :options="entities.map(e=>({label:e.name,value:e.id}))" placeholder="全部责任员工" aria-label="事项责任员工筛选"/></NSpace><NAlert v-if="error" type="error" role="alert">{{error}}<span class="alert-retry"><NButton @click="load()">重试</NButton></span></NAlert><NSpin :show="busy"><NEmpty v-if="!rows.length&&!error" description="暂无符合条件的事项"/><div v-else class="board-lanes"><section v-for="s in visibleStates" :key="s" class="board-lane"><header><h2>{{labels[s]}}</h2><span>{{rows.filter(r=>r.status===s).length}}</span></header><NCard v-for="item in rows.filter(r=>r.status===s)" :key="item.id" size="small" class="item-card"><NButton text class="item-title" @click="emit('selected',item.id)">{{item.title}}</NButton><p v-if="item.summary">{{item.summary}}</p><div class="item-meta"><span>{{employeeName(item.ownerEmployeeId)}}<NTag v-if="item.assignmentKind==='acceptance'" size="small" :bordered="false">验收环节</NTag></span><NTag v-if="item.betaPaused" size="small">交接待派发</NTag></div><p v-if="item.step" class="item-step">{{item.step}}</p><p v-if="item.pendingDispatch&&item.pendingDispatch.status!=='started'" class="item-wait">下一员工：{{employeeName(item.pendingDispatch.employeeId)}} · {{item.pendingDispatch.status==='blocked'?'派发受阻':item.pendingDispatch.status==='queued'?'已排队，尚未启动':'等待派发'}}</p><p v-if="item.waitReason" class="item-wait">{{item.waitReason}}</p></NCard><p v-if="!rows.some(r=>r.status===s)" class="lane-empty">暂无事项</p></section></div></NSpin><NButton v-if="cursor" :loading="busy" @click="load(true)">加载更多事项</NButton></template>
<NDrawer :show="!!selectedId" :width="'min(44rem, 100vw)'" placement="right" @update:show="v=>{if(!v)emit('selected',undefined)}"><NDrawerContent :title="detail?.item.title??'事项详情'" closable><NAlert v-if="detailError" type="error" role="alert">{{detailError}}<span class="alert-retry"><NButton @click="read(selectedId!)">重试</NButton></span></NAlert><NSpin :show="detailBusy"><template v-if="detail"><NSpace><NTag>{{labels[detail.item.status]}}</NTag><NTag v-if="detail.item.betaPaused">交接待派发</NTag></NSpace><dl class="business-fields"><dt>当前责任</dt><dd>{{employeeName(detail.item.ownerEmployeeId)}}<NTag v-if="detail.item.assignmentKind==='acceptance'" size="small" :bordered="false">验收环节</NTag></dd><template v-if="detail.item.pendingDispatch&&detail.item.pendingDispatch.status!=='started'"><dt>下一员工</dt><dd>{{employeeName(detail.item.pendingDispatch.employeeId)}} · {{detail.item.pendingDispatch.status==='blocked'?'派发受阻':detail.item.pendingDispatch.status==='queued'?'已排队，尚未启动':'等待派发'}}</dd></template><dt>发起员工</dt><dd>{{employeeName(detail.item.originEmployeeId)}}</dd><dt>业务目标</dt><dd>{{detail.item.goal}}</dd><dt>完成标准</dt><dd>{{detail.item.criteria}}</dd><dt>当前进展</dt><dd>{{detail.item.summary||'尚无进展'}}</dd><template v-if="detail.item.nextStep"><dt>下一步</dt><dd>{{detail.item.nextStep}}</dd></template><template v-if="detail.item.waitReason"><dt>等待原因</dt><dd>{{detail.item.waitReason}}</dd></template><template v-if="detail.item.completionEvidence"><dt>完成证据</dt><dd>{{detail.item.completionEvidence}}</dd></template></dl><section v-if="detail.notifications?.length" aria-label="事项回告"><h3>结果回告</h3><p v-for="n in detail.notifications" :key="n.id">{{notificationStatus(n)}}</p></section><h3>交接链</h3><ol class="assignment-chain"><li v-for="(a,index) in detail.assignments" :key="a.id"><strong>{{employeeName(a.employeeId)}}</strong><span>{{a.kind==='acceptance'?`系统指派验收（提交员工：${employeeName(a.sourceEmployeeId)}）`:index===0?'发起':`由${employeeName(a.sourceEmployeeId)}交接`}}</span><p>{{a.summary}}</p><time>{{date(a.createdAt)}}</time></li></ol><h3>业务活动</h3><ol class="activity-list"><li v-for="event in detail.events" :key="event.id"><strong>{{({created:'创建事项',acceptance_requested:'提交成果，系统指派验收',accepted:'验收通过',system_state:'系统状态更新',task_started:'执行已开始',handed_off:'直接交接',progress:'业务进展',task_queued:'目标任务已排队',beta_paused:'交接待派发',beta_resumed:'Beta恢复'}as Record<string,string>)[event.kind]??event.kind}}</strong><time>{{date(event.createdAt)}}</time><p v-if="event.body.summary">{{event.body.summary}}</p><p v-if="event.body.reason">{{event.body.reason}}</p><p v-if="event.body.waitReason">{{event.body.waitReason}}</p></li></ol><NButton v-if="detail.nextCursor" :loading="detailBusy" @click="read(selectedId!,true)">加载后续活动</NButton></template></NSpin></NDrawerContent></NDrawer></section></template>
<style scoped>.work-items-page{min-width:0}.board-filters{margin:1rem 0}.board-filters :deep(.n-select){width:14rem}.board-lanes{display:flex;gap:1rem;overflow:auto;max-width:100%;padding:.25rem 0 1rem}.board-lane{flex:1 0 15rem;min-width:0;border-radius:var(--id-radius-card);background:var(--id-bg-canvas);padding:.75rem}.board-lane>header{display:flex;justify-content:space-between;align-items:center;margin-bottom:.75rem}.board-lane h2{font-size:.875rem;margin:0}.board-lane header span,.lane-empty,.item-meta,.item-step,time{color:var(--id-text-secondary);font-size:.8125rem}.item-card{margin-bottom:.75rem}.item-title{font-weight:600;white-space:normal;text-align:left;max-width:100%;height:auto;overflow-wrap:anywhere}.item-card p{white-space:pre-wrap;overflow-wrap:anywhere;font-size:.875rem}.item-meta{display:flex;justify-content:space-between;gap:.5rem}.item-wait{color:var(--id-warning)}.business-fields{display:grid;grid-template-columns:5rem minmax(0,1fr);gap:.75rem 1rem;margin:1.5rem 0}.business-fields dt{color:var(--id-text-secondary)}.business-fields dd{margin:0;white-space:pre-wrap;overflow-wrap:anywhere}.assignment-chain,.activity-list{padding-left:1.25rem}.assignment-chain li,.activity-list li{margin:1rem 0;overflow-wrap:anywhere}.assignment-chain span,.activity-list time{display:block}.assignment-chain p,.activity-list p{white-space:pre-wrap;margin:.4rem 0}.work-items-page :deep(.n-alert){margin-bottom:1rem}@media(max-width:600px){.board-lanes{display:block;overflow:visible}.board-lane{margin-bottom:1rem}.board-filters :deep(.n-select){width:min(16rem,85vw)}}
</style>
